// What the app says happened (src/lib/activityEmail.ts), and who hears of it.
// Anyone can call this webhook. For a client or Team One only known kinds and
// whole counts go on: the next steps find the address themselves and write
// every word. FTG's own email is written here, with everything from the
// request escaped, and it only ever goes to accounting@.
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const line = (s, max) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, max);

const b = $input.first().json.body || {};
const audience = String(b.audience ?? '');
const email = line(b.client_email, 200).toLowerCase();
if (!/^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(email)) return [];

if (audience === 'ftg') {
  const who = line(b.client_name, 120) || email;
  const list = (v, max) => (Array.isArray(v) ? v : []).map(x => String(x ?? '').trim().slice(0, max)).filter(Boolean).slice(0, 20);
  const updates = list(b.updates, 400).map(u => line(u, 400));
  const messages = list(b.messages, 4000);
  if (!updates.length && !messages.length) return [];
  const both = updates.length && messages.length;
  const subject = both ? `Team One sent an update and wrote about ${who}`
    : updates.length ? `Team One sent an update for ${who}` : `Team One wrote about ${who}`;
  const did = both ? 'sent an update and wrote in the Team One chat for'
    : updates.length ? 'sent an update for' : 'wrote in the Team One chat for';
  let html = `<p><b>Team One</b> ${did} <b>${esc(who)}</b>${who !== email ? ' (' + esc(email) + ')' : ''}.</p>`;
  if (updates.length) {
    html += `<ul>${updates.map(u => `<li>${esc(u)}</li>`).join('')}</ul>`
      + '<p>Review it under <b>Team One</b> in the app.</p>';
  }
  if (messages.length) {
    html += messages.map(m => `<div style="margin:12px 0;padding:10px 14px;border-left:3px solid #E8B923;background:#FBF7EE;white-space:pre-wrap">${esc(m)}</div>`).join('')
      + "<p>To reply, open the client's profile and use <b>Team One chat</b>.</p>";
  }
  html += `<p><a href="${APP}">Open the portal</a></p>`;
  return [{ json: { audience, client_email: email, subject, html } }];
}

const kinds = audience === 'client' ? ['accepted', 'declined', 'replies', 'notes']
  : audience === 'team_one' ? ['access', 'messages', 'approved', 'sent_back', 'escalated', 'noted']
  : null;
if (!kinds) return [];
const counts = {};
for (const k of kinds) {
  const n = Math.floor(Number(b.counts?.[k]));
  if (n > 0) counts[k] = Math.min(n, 99);
}
if (!Object.keys(counts).length) return [];
return [{ json: { audience, client_email: email, counts } }];

// The email to a client about what FTG did in their portal. Every word is
// written here: the request said only how many of each ("Check it"), and the
// address and name come from email_ready_clients ("Find the client"), so only
// a client who has signed in or been invited ever gets one.
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const c = $input.first().json;
const counts = $('Check it').first().json.counts || {};
const n = k => counts[k] || 0;
// [the sentence, the subject when it is the only news]
const news = [];
if (n('accepted')) news.push(n('accepted') === 1
  ? ['We accepted your file.', 'We accepted your file']
  : [`We accepted ${n('accepted')} of your files.`, `We accepted ${n('accepted')} of your files`]);
if (n('declined')) news.push(n('declined') === 1
  ? ['We sent a file back to you. Sign in to see why, then upload it again.', 'We sent a file back to you']
  : [`We sent ${n('declined')} files back to you. Sign in to see why, then upload them again.`, `We sent ${n('declined')} files back to you`]);
if (n('replies')) news.push(n('replies') === 1
  ? ['We sent you a message about one of your files.', 'New message from Finance Therapy Group']
  : [`We sent you ${n('replies')} messages about your files.`, `${n('replies')} new messages from Finance Therapy Group`]);
if (n('notes')) news.push(n('notes') === 1
  ? ['We left you a note.', 'A note from Finance Therapy Group']
  : [`We left you ${n('notes')} notes.`, `${n('notes')} notes from Finance Therapy Group`]);
if (!news.length || !c.email) return [];

const first = c.first_name || String(c.full_name || '').trim().split(/\s+/)[0] || 'there';
const subject = news.length === 1 ? news[0][1] : 'Updates in your Finance Therapy Group portal';
const body = news.length === 1 ? `<p>${news[0][0]}</p>`
  : `<p>Here's what's new in your Finance Therapy Group portal:</p><ul>${news.map(x => `<li>${x[0]}</li>`).join('')}</ul>`;
const html = `<p>Hi ${esc(first)},</p>${body}`
  + `<p><a href="${APP}">Sign in to the portal</a></p>`
  + '<p>Thank you,<br>Finance Therapy Group</p>';
return [{ json: { to: c.email, subject, html } }];

// The email to Team One about one of its clients. Every word is written here:
// the request said only how many of each ("Check it"), the client's name comes
// from team_one_clients, so only a client Team One has, and the addresses from
// email_ready_team_one ("Find Team One"). One email per Team One login.
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const counts = $('Check it').first().json.counts || {};
const client = $("Is it Team One's client?").first().json;
const who = String(client.name || client.email_key || 'a client').replace(/[\r\n\t]+/g, ' ').trim();
const W = esc(who);
const n = k => counts[k] || 0;
const say = (k, one, many) => n(k) === 1 ? one : many.replace('#', n(k));
// [the sentence, the subject when it is the only news]
const news = [];
if (n('access')) news.push([`FTG gave you access to <b>${W}</b> in the Finance Therapy Group app.`, `You now have ${who} in the FTG app`]);
if (n('messages')) news.push([say('messages', `FTG sent you a message in ${W}'s Team One chat.`, `FTG sent you # messages in ${W}'s Team One chat.`), `${who}: new message from FTG`]);
if (n('approved')) news.push([say('approved', 'FTG approved one of your items and filed it for the client.', 'FTG approved # of your items and filed them for the client.'), `${who}: FTG approved your work`]);
if (n('sent_back')) news.push([say('sent_back', 'FTG sent an item back to you to fix. Their note says what to change.', 'FTG sent # items back to you to fix. Their notes say what to change.'), `${who}: an item needs fixing`]);
if (n('escalated')) news.push([say('escalated', 'An item went to Daja for a second look.', '# items went to Daja for a second look.'), `${who}: an item went to Daja`]);
if (n('noted')) news.push([say('noted', 'Daja answered an item with a note to the client.', 'Daja answered # items with a note to the client.'), `${who}: Daja left the client a note`]);
if (!news.length) return [];

const subject = news.length === 1 ? news[0][1] : `${who}: updates from FTG`;
const body = news.length === 1 ? `<p>${news[0][0]}</p>`
  : `<p>Here's what's new for <b>${W}</b>:</p><ul>${news.map(x => `<li>${x[0]}</li>`).join('')}</ul>`;
return $input.all().filter(i => i.json.email).map(i => {
  const first = i.json.first_name || String(i.json.full_name || '').trim().split(/\s+/)[0] || 'Team One';
  return { json: {
    to: i.json.email,
    subject,
    html: `<p>Hi ${esc(first)},</p>${body}<p><a href="${APP}">Open the app</a></p><p>Thank you,<br>Finance Therapy Group</p>`,
  } };
});
